  "hypothesis": "Replacing fixed-temperature packet repair with a timed smooth-max continuation will escape the incumbent's sharp peak constraints and produce a verified gain of at least 1e-5.",
  "rationale": "The existing cut-and-reflection search followed by very sharp repair has produced only approximately 1e-12 gains, consistent with immediately returning to the same nonsmooth local optimum. Beginning repair with a softer maximum and progressively sharpening it permits coordinated packet-weight changes before enforcing the exact peak constraint; exact verification still protects the warm start.",
  "source": "import time
import numpy as np
import scipy.fft as fft
from scipy.signal import oaconvolve
from scipy.optimize import minimize

PARAMS = {
    'search_fraction': (0.43, 0.15, 0.55),
    'total_fraction': (0.70, 0.50, 0.73),
    'repair_tolerance': (0.0003, 0.000001, 0.01, 'log'),
    'beta': (3e8, 1e6, 1e11, 'log'),
    'initial_beta': (3000.0, 100.0, 1000000.0, 'log'),
    'cuts': (36, 12, 120),
}


def decode(obj):
    if 'values' in obj:
        return np.maximum(np.asarray(obj['values'], dtype=float), 0.0)
    a = np.maximum(np.asarray(obj['ring'], dtype=float), 0.0)
    k = int(obj.get('cut', 0))
    mode = int(obj.get('reflection', 0))
    if mode == 1:
        return np.concatenate((a[:k][::-1], a[k:]))
    if mode == 2:
        return np.concatenate((a[:k], a[k:][::-1]))
    return np.concatenate((a[k:], a[:k])) if k else a.copy()


def exact_score(f):
    c = oaconvolve(f, f, mode='full')
    x = np.linspace(-0.5, 0.5, len(c) + 2)
    y = np.concatenate(([0.0], c, [0.0]))
    a, b = y[:-1], y[1:]
    num = float(np.sum((np.diff(x) / 3.0) * (a*a + a*b + b*b)))
    return float(num / ((np.sum(np.abs(c)) / (len(c)+1)) * np.max(np.abs(c))))


def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + float(params['total_fraction']) * budget_s
    search_end = start + float(params['search_fraction']) * budget_s
    if init is None:
        return {'values': [1.0]}
    f0 = decode(init)
    baseline = exact_score(f0)
    n = len(f0)
    if n < 4 or time.monotonic() >= deadline:
        return init
    rng = np.random.default_rng(seed)
    f0 = f0 / float(f0.max())
    m = fft.next_fast_len(2*n-1, real=True)
    best_score = baseline
    best_f = None
    contender = None
    contender_score = -np.inf

    def approximate(f):
        s = fft.rfft(f, m)
        c = fft.irfft(s*s, m)[:2*n-1]
        return float((2*np.dot(c, c) + np.dot(c[:-1], c[1:])) /
                     (3*np.sum(np.abs(c))*np.max(np.abs(c))))

    def make(k, mode):
        if mode == 0:
            return np.concatenate((f0[k:], f0[:k]))
        if mode == 1:
            return np.concatenate((f0[:k][::-1], f0[k:]))
        return np.concatenate((f0[:k], f0[k:][::-1]))

    def inspect(k, mode):
        nonlocal best_score, best_f, contender, contender_score
        if time.monotonic() >= search_end:
            return
        f = make(k, mode)
        score = approximate(f)
        if score > contender_score:
            contender_score = score
            contender = f
        if score > best_score - 2e-13 and time.monotonic() < deadline-1.0:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()

    cuts = set()
    cumulative = np.cumsum(f0)
    for q in np.linspace(0.01, 0.99, int(params['cuts'])):
        if time.monotonic() >= search_end:
            break
        cuts.add(int(np.searchsorted(cumulative, q*cumulative[-1])))
    for d in np.geomspace(1, max(2, n//3), 18):
        if time.monotonic() >= search_end:
            break
        k = int(d)
        cuts.add(k)
        cuts.add(n-k)
    occupied = f0 > 0
    changes = np.flatnonzero(occupied[1:] != occupied[:-1]) + 1
    edges = np.r_[0, changes, n]
    widths = np.diff(edges)
    for j in np.argsort(widths)[::-1][:24]:
        if time.monotonic() >= search_end:
            break
        if not occupied[edges[j]]:
            cuts.add(int((edges[j]+edges[j+1])//2))
            cuts.add(int(edges[j]))
            cuts.add(int(edges[j+1]))
    jobs = []
    for k in sorted(cuts):
        if time.monotonic() >= search_end:
            break
        if 0 < k < n:
            jobs.extend(((k, 0), (k, 1), (k, 2)))
    rng.shuffle(jobs)
    for k, mode in jobs:
        if time.monotonic() >= search_end:
            break
        inspect(k, mode)

    def result():
        if best_f is None:
            return init
        return {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}

    if contender is None or contender_score < baseline - float(params['repair_tolerance']):
        return result()
    if time.monotonic() >= deadline - 2.0:
        return result()

    spec = fft.rfft(contender, m)
    peak = fft.irfft(spec*spec, m)[:2*n-1].max()
    base = contender / np.sqrt(peak)
    indices = np.flatnonzero(base > 0)
    starts = np.r_[True, (np.diff(indices) != 1) | (indices[1:]//256 != indices[:-1]//256)]
    labels = np.cumsum(starts, dtype=np.int64)-1
    groups = int(labels[-1])+1
    active = base[indices]

    class StageStop(Exception):
        pass

    def materialize(x):
        f = np.zeros(n)
        f[indices] = active*np.square(x[labels])
        return f

    # Continue the same packet-weight optimization through successively sharper
    # peak models. Each stage restarts curvature estimates, but keeps its best
    # smooth-objective iterate, including when interrupted by its time slice.
    repair_start = time.monotonic()
    repair_end = deadline - 1.5
    fractions = (0.20, 0.43, 0.68, 1.0)
    betas = np.geomspace(min(float(params['initial_beta']), float(params['beta'])),
                        float(params['beta']), len(fractions))
    x = np.ones(groups)
    for stage, beta in enumerate(betas):
        if time.monotonic() >= repair_end:
            break
        stage_end = repair_start + fractions[stage]*(repair_end-repair_start)
        stage_best_x = x.copy()
        stage_best_value = np.inf

        def objective(v):
            nonlocal best_score, best_f, stage_best_x, stage_best_value
            if time.monotonic() >= stage_end:
                raise StageStop()
            f = materialize(v)
            sp = fft.rfft(f, m)
            c = fft.irfft(sp*sp, m)[:2*n-1]
            peak = c.max()
            e = np.exp(beta*(c-peak))
            z = e.sum()
            smooth = peak + np.log(z)/beta
            num = (2*np.dot(c,c)+np.dot(c[:-1],c[1:]))/3
            total = f.sum()
            quick = num/(np.sum(np.abs(c))*np.max(np.abs(c)))
            if quick > best_score + 1e-13 and time.monotonic() < deadline-1.0:
                actual = exact_score(f)
                if actual > best_score:
                    best_score = actual
                    best_f = f.copy()
            value = -(np.log(num)-2*np.log(total)-np.log(smooth))
            if np.isfinite(value) and value < stage_best_value:
                stage_best_value = value
                stage_best_x = v.copy()
            g = 4*c
            g[1:] += c[:-1]
            g[:-1] += c[1:]
            g /= 3*num
            g -= e/(z*smooth)
            corr = fft.irfft(fft.rfft(g,m)*np.conj(sp),m)[:n]
            local = (2*corr[indices]-2/total)*active
            grad = 2*v*np.bincount(labels,weights=local,minlength=groups)
            return value, -grad

        try:
            minimize(objective, x, jac=True, method='L-BFGS-B',
                     options={'maxcor': 7, 'maxiter': 10000, 'maxfun': 20000,
                              'ftol': 0.0, 'gtol': 0.0, 'maxls': 15})
        except StageStop:
            pass
        x = stage_best_x
        # The soft maximum is not scale invariant. Keep the convolution peak
        # near one so each beta has its intended meaning throughout continuation.
        if time.monotonic() < repair_end-0.7:
            f = materialize(x)
            sp = fft.rfft(f, m)
            peak = float(fft.irfft(sp*sp, m)[:2*n-1].max())
            if peak > 0 and np.isfinite(peak):
                x = x / peak**0.25
    return result()
